// Resolve the mirror spreadsheet by name so no document id is stored in the workflow
// -- the sheet can be deleted and recreated without editing this.
//
// SECURITY: a name match proves uniqueness, NOT identity. Anyone can create a file
// with this name and share it with our service account; it then appears in the
// service account's Drive listing exactly like the real one. Both facts needed to do
// that (the service-account address and this sheet name) are published in a PUBLIC
// repo. So ownership is the actual authorisation check -- an attacker cannot make
// their file owned by our account.
//
// Fails closed three ways: owner not configured, no owned match, or more than one.
// `Find Sheet` sets alwaysOutputData so the zero-hit case still reaches this node;
// without it this would not run at all and the sync would silently no-op.
const want = $env.lead_sheet_name ?? 'Prudentia Leads Mirror';
const owner = ($env.lead_sheet_owner ?? '').trim().toLowerCase();

if (!owner) {
  throw new Error(
    'lead_sheet_owner is not set. Refusing to resolve the mirror spreadsheet by name ' +
    'alone: name matching proves uniqueness, not identity, and anyone can share a ' +
    'same-named file with this service account. Set it from the lead-pipeline Vault path.'
  );
}

const owned = $input.all().filter((i) => {
  const o = i.json && i.json.owners;
  return i.json && i.json.id && Array.isArray(o) &&
    o.some((x) => String(x.emailAddress ?? '').toLowerCase() === owner);
});

if (owned.length !== 1) {
  const seen = $input.all().filter((i) => i.json && i.json.id).length;
  throw new Error(
    `Sheet mirror: expected exactly 1 spreadsheet named "${want}" owned by ${owner}, ` +
    `found ${owned.length} (${seen} name match(es) total). Check the name, that it is ` +
    `not in the trash, that it is shared with the service account, and that it is owned ` +
    `by the configured account.`
  );
}

return [{ json: { sheet_id: owned[0].json.id, sheet_name: owned[0].json.name } }];
